def find_min_sum(target):
    # k[i] is the coefficient of r^i
    # Use the relation 10*r^i = r^{i+1} + r^{i+2} + r^{i+3}
    # This reduces the sum of coefficients by 7.
    # To minimize the sum, we should apply this as much as possible.
    k = [0] * 200
    k[0] = target

    changed = True
    while changed:
        changed = False
        for i in range(190):
            if k[i] >= 10:
                num = k[i] // 10
                k[i] -= 10 * num
                k[i+1] += num
                k[i+2] += num
                k[i+3] += num
                changed = True
    return sum(k)

print(find_min_sum(2025))
